from pathlib import Path
import json,csv
N=Path(__file__).resolve().parents[1]; P=N/'power'; rows=[]
def add(ident,a,b,signal,source,status='PIN_DEFINED_CANDIDATE',note=''):
 rows.append(dict(id=ident,from_endpoint=a,to_endpoint=b,signal=signal,source=source,status=status,note=note,physical_test='NOT_EXECUTED',cut_length_mm=None))
for i in range(1,5):add(f'BP{i:02}',f'BPX.PBAT2.{i}',f'DOCK.P4.{i+4}','EPS_RET','BPX1.1.0 §3.4; Dock3.1 §12')
for i in range(5,9):add(f'BP{i:02}',f'BPX.PBAT2.{i}',f'DOCK.P4.{i-4}','VBAT_DIRECT_RAW','BPX1.1.0 §3.4; Dock3.1 §12',note='4 pins total current shared; raw battery no short-circuit protection')
for i,j,signal in [(9,2,'I2C_SCL'),(10,4,'BPX_ENABLE_ACTIVE_HIGH'),(11,3,'I2C_SDA'),(12,1,'EPS_RET')]:add(f'BP{i:02}',f'BPX.PBAT2.{i}',f'DOCK.P5.{j}',signal,'BPX1.1.0 §3.4; Dock3.1 §12')
for i in [13,14]:add(f'BP_NC{i}',f'BPX.PBAT2.{i}','NC','NC','BPX1.1.0 §3.4','INTENTIONALLY_NOT_CONNECTED','Pin14 conflicts with Dock3.1 §12 legacy kill-switch table; current BPX NC wins')
for ch,pins in {0:[1,3],1:[5,7],2:[9,11],3:[13,15],4:[17,19,21,23],5:[25,27,29]}.items():
 for pin in pins:add(f'PV{ch}_{pin}',f'PV_BRANCH_{ch}.BLOCKED_POS',f'ACU.X1.TFM.{pin}',f'PV{ch}+','ACU2.3 §3.1','PIN_DEFINED_ARRAY_UNBOUND','Each parallel string requires separate series blocking diode; cell bypass diode is different')
 for pin in [x+1 for x in pins]:add(f'PV{ch}_RET{pin}',f'PV_BRANCH_{ch}.RET',f'ACU.X1.TFM.{pin}','PV_RET','ACU2.3 §3.1','PIN_DEFINED_ARRAY_UNBOUND')
add('L01','PDU.X2.TFM.9','A3200.P1.2','OBC_3V3','PDU2.6 §3.1; A3200 2.0 §3.1.1',note='Exclusive standalone ground P1 topology; all FSI supply removed')
add('L02','PDU.X2.TFM.10','A3200.P1.1','EPS_RET','PDU2.6 §3.1; A3200 2.0 §3.1.1')
for i,j in [(1,1),(2,2),(3,3),(4,4)]:add(f'FPP_CH{i}',f'GSE_CHARGER.{["RETURN1","RETURN2","SENSE","CHARGE+"][i-1]}',f'DOCK.P13.{j}',['EPS_RET','EPS_RET','VBAT_SENSE','VBAT_CHARGE'][i-1],'Dock3.1 §5.4','REQUIREMENT_ONLY_EXTERNAL_CHARGER_UNSELECTED','FPP current <=1 A; no feed to P13.5 VBAT_DIRECT for spacecraft-off charge')
for ident,a,b,net,note in [('RBF','FPP.RBF_JUMPER','DOCK.P14.6','RBF_ACTIVE_LOW','Grounded=inhibit; 2Mohm pull-up to VBAT at FPP and 220ohm series near Dock per3.1 §5.1; floating exposed forbidden'),('DEARM','FPP.DEARM_JUMPER','DOCK.P14.7','DEARM_ACTIVE_LOW','Grounded=antenna release inhibited; all deployment commands remain disabled'),('KILL1','DEPLOY_SWITCH1','DOCK.P10.4','KILL1','P10 parallel vsP11 series configuration must not be mixed'),('KILL2','DEPLOY_SWITCH2','DOCK.P10.2','KILL2','P11 series selected instead only via supplier-confirmed detailed connector mapping')]:add(ident,a,b,net,'Dock3.1 §3–5','INTERFACE_DEFINED_SWITCH_PART_UNBOUND',note)
for ident,a,b,net in [('K1_PWR','Q1.2','K1.A2(+)','ARM_24V_PROTECTED'),('K1_OUT','K1.A1(-)','U1.IN+','ARM_24V_SWITCHED'),('K1_COILP','STOP_CONTROL.PROTECTED_24V','K1.X1(+)','COIL24'),('K1_COILR','K1.X2(-)','STOP_CONTROL.RETURN','COIL_RET'),('K1_FB1','K1.T1','STOP_MONITOR.INPUT','AUX_NO'),('K1_FB2','K1.T2','STOP_MONITOR.REFERENCE','AUX_NO')]:add(ident,a,b,net,'GX11 Rev6 10/23/15 p3–4','PIN_DEFINED_CONTROL_HARDWARE_UNBOUND','Main current direction A2→A1. Aux NO mechanically linked is observation, not validated safety mirror contact. Coil source upstream K1. No external flyback diode.')
with (P/'POWER_FROM_TO.csv').open('w',newline='',encoding='utf-8-sig') as f:w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows(rows)
contract={'identity':'Endpoint contract; not assembled harness or native EDA netlist','selected_configuration':{'Dock_voltage':'8S 24–33.6 V hardware; normal24–32 V','X1':'ACU200','X2':'PDU200','X3':'only factory-configured A3200 when FSI mode; empty in current standalone P1 mode','X4':'empty','PDU_regulator0':'12V only CH1/CH6 high-regulated option','PDU_regulator1':'3.3V CH2 OBC','PDU_regulator2':'5V CH0/CH3/CH5 allocations; other channel states OFF'},'endpoints':rows,'critical_conflicts':[{'id':'BPX_PIN14','source1':'Dock3.1 §12: PBAT2.14 toP5.7','source2':'BPX100Wh1.1.0 §3.4: PBAT2.14 NC','disposition':'Leave PBAT2.14 andDockP5.7 unconnected and insulated. Require exact assembled vendor harness revision; do not infer compatibility.'},{'id':'A3200_X3_VBAT','source1':'Dock3.1 §3.1 permits A3200 onlyX3 and requires VBAT-removal option','source2':'Generic X3A pin table carriesVBAT on9/10/13–16','disposition':'No generic FSI plug-in. Factory assembled option must suppress incompatibleVBAT nets; P1/FSI mutually exclusive.'},{'id':'ACU_TYPICAL_GRAPH','source1':'ACU2.3 §7 efficiency measured at7/8V battery','source2':'Current8S24–32V','disposition':'Use0.80 efficiency as project requirement, not inherited measured guarantee.'}], 'physical_tests':0,'build_approved':False}
(P/'POWER_ENDPOINT_CONTRACT.json').write_text(json.dumps(contract,ensure_ascii=False,indent=2),encoding='utf-8')
print(len(rows))
